// --- Pairing & Auth ---

/**
 * `POST /v1/pair` body. Names/UUIDs are display data; a challenge signature
 * proves computer-key ownership. Narrow UOA account grants use their own proof.
 */
export interface PairRequest {
  /** Stable per-install UUID generated by the CLI. */
  clientId: string;
  /** Human-readable client name, such as `username@hostname`. Truncated to 64 chars. */
  clientName: string;
  /** Request a hidden challenge and present a narrow UOA proof instead of manual approval. */
  account?: true;
  requestId?: string;
  accountTicket?: string;
  /** Raw Ed25519 public key in lowercase hex; stable across addresses and ports. */
  computerPublicKey?: string;
  /** Signature over the server challenge and public key. */
  computerSignature?: string;
}

/** Initial response from `POST /v1/pair`. */
export interface PairResponse {
  status: "pending" | "computer_challenge";
  /** False during the challenge or when the signing key is already trusted and no dialog is needed. */
  approvalRequired?: boolean;
  /** Server-issued 32-byte CSPRNG nonce used to poll status. */
  requestId: string;
  /** Unix epoch ms when the pending request expires. */
  expiresAt: number;
  /** Authoritative socket peer address as seen by the server. */
  sourceAddress: string;
}

/**
 * Scope of an approved pairing.
 *
 * - `session`: kept in device memory only; cleared on app restart.
 * - `persistent`: its hash is stored with the approved computer key; survives restart.
 */
export type PairScope = "session" | "persistent";

export type PairStatusState =
  | "pending"
  | "approved"
  | "denied"
  | "expired"
  | "not_found"
  | "error";

/**
 * `GET /v1/pair/status?requestId=...` response. The plaintext `token` is
 * returned exactly once on approval; the pending entry is deleted server-side
 * immediately afterwards.
 */
export interface PairStatusResponse {
  status: PairStatusState;
  scope?: PairScope;
  token?: string;
}

/** `GET /v1/get-device-info` advertises that pairing is required. */
export interface DeviceInfoPairing {
  name: string;
  platform: string;
  version: string;
  requiresPairing: boolean;
  approvalMode?: "computer-key";
  localhostTrusted?: boolean;
}
